// Every value the web calculator computes must match the tested Python package (ckdtools) to 1e-9.
// Reference values: test/reference_values.json, generated by scripts/make_reference.py.
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import {
  albuminuriaCategory, egfrCreatinine, egfrCreatinineCystatin, egfrCystatin, gfrCategory, kdigoRisk, kfre,
  CREATININE_UMOL_PER_MGDL, ACR_MGG_PER_MGMMOL,
} from "../calc.js";

const ref = JSON.parse(readFileSync(new URL("./reference_values.json", import.meta.url)));
const close = (a, b, msg) => assert.ok(Math.abs(a - b) < 1e-9 * Math.max(1, Math.abs(b)), `${msg}: ${a} vs ${b}`);

test("eGFR equations match ckdtools", () => {
  const cases = ref.filter((c) => c.kind === "egfr");
  assert.ok(cases.length > 200);
  for (const c of cases) {
    const id = JSON.stringify([c.age, c.sex, c.scr, c.scys]);
    close(egfrCreatinine(c.scr, c.age, c.sex), c.egfr_cr, `cr ${id}`);
    close(egfrCystatin(c.scys, c.age, c.sex), c.egfr_cys, `cys ${id}`);
    close(egfrCreatinineCystatin(c.scr, c.scys, c.age, c.sex), c.egfr_cr_cys, `cr-cys ${id}`);
  }
});

test("KFRE matches ckdtools for both calibrations and horizons", () => {
  for (const c of ref.filter((c) => c.kind === "kfre")) {
    const id = JSON.stringify([c.age, c.sex, c.egfr, c.acr, c.region]);
    close(kfre(c.age, c.sex, c.egfr, c.acr, { years: 2, region: c.region }), c.kfre2, `2y ${id}`);
    close(kfre(c.age, c.sex, c.egfr, c.acr, { years: 5, region: c.region }), c.kfre5, `5y ${id}`);
  }
});

test("KDIGO categories and heat map match ckdtools, including boundaries", () => {
  for (const c of ref.filter((c) => c.kind === "kdigo")) {
    assert.equal(gfrCategory(c.egfr), c.g, `G for ${c.egfr}`);
    assert.equal(albuminuriaCategory(c.acr), c.a, `A for ${c.acr}`);
    assert.equal(kdigoRisk(c.g, c.a), c.risk);
  }
});

test("SI units are equivalent to conventional units", () => {
  close(egfrCreatinine(CREATININE_UMOL_PER_MGDL, 55, "male", "umol/L"), egfrCreatinine(1.0, 55, "male"), "creatinine");
  close(kfre(60, "female", 40, 30, { acrUnit: "mg/mmol" }), kfre(60, "female", 40, 30 * ACR_MGG_PER_MGMMOL), "ACR");
});

test("invalid input is rejected", () => {
  assert.throws(() => egfrCreatinine(1.0, 17, "male"));
  assert.throws(() => egfrCreatinine(0, 50, "male"));
  assert.throws(() => egfrCreatinine(1.0, 50, "other"));
  assert.throws(() => kfre(60, "male", 30, 100, { years: 3 }));
});
